// Extract and validate incoming message
const body = $input.first().json.body || $input.first().json;

const message = body.message || '';
const sessionId = body.sessionId || `session-${Date.now()}`;
const visitorName = body.visitorName || '';
const visitorEmail = body.visitorEmail || '';
const conversationHistory = body.conversationHistory || [];

if (!message || message.trim().length === 0) {
  throw new Error('Empty message received');
}

console.log(`[PG Chatbot] Session: ${sessionId}, Message: ${message.substring(0, 50)}...`);

return [{
  json: {
    message: message.trim(),
    sessionId,
    visitorName,
    visitorEmail,
    conversationHistory,
    timestamp: new Date().toISOString()
  }
}];

// Prepare query vector and preserve session data
const embedResponse = $input.first().json;
const sessionData = $('Extract Message Data').first().json;

const queryVector = embedResponse.data[0].embedding;

return [{
  json: {
    ...sessionData,
    queryVector
  }
}];

// Build the context from Pinecone results
const pineconeResponse = $input.first().json;
const sessionData = $('Prepare Query Vector').first().json;

// Extract relevant text chunks
const matches = pineconeResponse.matches || [];
const context = matches
  .filter(m => m.score > 0.3)
  .map(m => m.metadata?.text || '')
  .filter(t => t.length > 0)
  .join('\n\n---\n\n');

// Detect intent from message for routing
const message = sessionData.message.toLowerCase();
let intent = 'general';

if (message.includes('book') || message.includes('call') || message.includes('appointment') || 
    message.includes('schedule') || message.includes('meet') || message.includes('talk')) {
  intent = 'booking';
} else if (message.includes('price') || message.includes('cost') || message.includes('much') || 
           message.includes('fee') || message.includes('charge') || message.includes('invest')) {
  intent = 'pricing';
} else if (message.includes('human') || message.includes('person') || message.includes('real') || 
           message.includes('chad') || message.includes('deepak') || message.includes('team')) {
  intent = 'escalation';
} else if (message.includes('what do you do') || message.includes('how does') || 
           message.includes('what is') || message.includes('tell me about')) {
  intent = 'services';
}

// Build conversation history string
const historyString = sessionData.conversationHistory
  .slice(-6)
  .map(h => `${h.role === 'user' ? 'Visitor' : 'Process Gravity AI'}: ${h.content}`)
  .join('\n');

return [{
  json: {
    ...sessionData,
    context,
    intent,
    historyString,
    matchCount: matches.length
  }
}];

// Extract Claude response and prepare final output
const claudeResponse = $input.first().json;
const sessionData = $('Build Context and Detect Intent').first().json;

const aiResponse = claudeResponse.content?.[0]?.text || 
  'I apologize, I am having trouble responding right now. Please try again or email us at hello@processgravity.com';

const intent = sessionData.intent;
const showBookingButton = intent === 'booking' || 
  aiResponse.toLowerCase().includes('discovery call') || 
  aiResponse.toLowerCase().includes('book') ||
  aiResponse.toLowerCase().includes('60 minutes');

// Check if we should capture lead info
const shouldCaptureLead = intent === 'booking' || intent === 'escalation';

// Update conversation history
const updatedHistory = [
  ...(sessionData.conversationHistory || []),
  { role: 'user', content: sessionData.message },
  { role: 'assistant', content: aiResponse }
].slice(-20); // Keep last 20 messages

return [{
  json: {
    sessionId: sessionData.sessionId,
    message: sessionData.message,
    response: aiResponse,
    intent,
    showBookingButton,
    shouldCaptureLead,
    calendlyUrl: 'https://calendly.com/processgravity/discovery',
    visitorName: sessionData.visitorName,
    visitorEmail: sessionData.visitorEmail,
    updatedHistory,
    timestamp: sessionData.timestamp
  }
}];

